"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["26227"],{28014(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.matriz_divergente_da_regra","status":422,"titulo":"A ordem de remanejamento informada diverge da declara\xe7\xe3o da regra referenciada"},"descricao":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.matriz_divergente_da_regra","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["O `fallbackCodigo` e/ou os `destinos` declarados no corpo do pedido de defini\xe7\xe3o da\\ncascata n\xe3o reproduzem, c\xe9lula a c\xe9lula, o `esquema_args` congelado da\\nvers\xe3o da regra referenciada. A regra de remanejamento n\xe3o\\n\xe9 s\xf3 uma refer\xeancia solta \u2014 a vers\xe3o do cat\xe1logo j\xe1 traz a matriz completa\\nde fallback e destinos por origem, e o corpo do pedido da defini\xe7\xe3o precisa\\ndeclar\xe1-la de volta, igual, n\xe3o apenas em uma forma v\xe1lida qualquer.","\xc9 a distin\xe7\xe3o entre **forma** e **conte\xfado** que a s\xe9rie inteira desta\\nsub-fatia carrega: as demais causas conferem se a matriz \xe9 internamente\\ncoerente (fallback presente, destinos n\xe3o vazios, ordens \xfanicas e\\ncont\xedguas por origem, sem destino repetido) \u2014 esta confere se, al\xe9m de\\ncoerente, a matriz \xe9 a **mesma** que a regra do cat\xe1logo j\xe1 define. Uma\\nmatriz pode passar por todas as confer\xeancias de forma e ainda assim divergir\\ndo conte\xfado esperado.","Roda por \xfaltimo, depois de a regra j\xe1 ter sido resolvida e confirmada como\\n`CRITERIO_REMANEJAMENTO` \u2014 \xe9 a \xfanica confer\xeancia desta s\xe9rie que depende do\\n`esquema_args` da regra, ent\xe3o n\xe3o pode rodar antes dela ser resolvida.\\nSequencial: n\xe3o acumula com nenhuma outra causa."],"comoResolver":["Confira, no cat\xe1logo de regras, o `esquema_args` da vers\xe3o referenciada \u2014\\nele lista o fallback e a matriz de destinos por origem esperados. Ajuste o\\ncorpo do pedido de defini\xe7\xe3o da cascata para reproduzir exatamente essa matriz,\\ninclusive a ordem dos destinos dentro de cada origem."],"ondeAparece":["Defini\xe7\xe3o de cascata de remanejamento do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao cascata remanejamento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);